<?php
declare(strict_types=1);
require_once __DIR__.'/data.php';
$defs=[
 'sales'=>['title'=>'Sales','eyebrow'=>'REVENUE OPERATIONS','desc'=>'Record and review product sales across every branch and brand.','table'=>'sales','items'=>'sale_items','date'=>'sale_date','prefix'=>'SAL','type'=>'sale','direction'=>'out','amount'=>'total_amount','permission'=>'sales.create'],
 'receiving'=>['title'=>'Stock Receiving','eyebrow'=>'INBOUND STOCK','desc'=>'Receive supplier stock and update inventory safely.','table'=>'stock_receivings','items'=>'stock_receiving_items','date'=>'received_date','prefix'=>'RCV','type'=>'receiving','direction'=>'in','amount'=>'total_cost','permission'=>'receiving.create'],
 'usage'=>['title'=>'Stock Usage','eyebrow'=>'INTERNAL CONSUMPTION','desc'=>'Record operational usage with complete traceability.','table'=>'stock_usages','items'=>'stock_usage_items','date'=>'usage_date','prefix'=>'USE','type'=>'usage','direction'=>'out','amount'=>null,'permission'=>'usage.create'],
 'wastage'=>['title'=>'Wastage','eyebrow'=>'LOSS CONTROL','desc'=>'Track wastage quantity, reason and financial impact.','table'=>'wastages','items'=>'wastage_items','date'=>'wastage_date','prefix'=>'WST','type'=>'wastage','direction'=>'out','amount'=>'cost_impact','permission'=>'wastage.create'],
];
$d=$defs[$module];
if($_SERVER['REQUEST_METHOD']==='POST'){
 require_permission($d['permission']); verify_csrf();
 $product=(int)($_POST['product_id']??0);$qty=(float)($_POST['quantity']??0);$price=(float)($_POST['unit_price']??0);$branch=(int)($_POST['branch_id']??0);$brand=(int)($_POST['brand_id']??0);$date=$_POST['date']??date('Y-m-d');
 if(!$product||!$branch||!$brand||$qty<=0) { flash('error','Complete all required fields with a valid quantity.'); redirect($module.'.php?action=create'); }
 try{enforce_branch_scope($branch);$pdo->beginTransaction();$ref=next_reference($pdo,$d['prefix'],$d['table']);
  if($module==='sales'){$total=$qty*$price;$s=$pdo->prepare('INSERT INTO sales(reference_no,sale_date,branch_id,brand_id,payment_method,subtotal,total_amount,notes,created_by) VALUES(?,?,?,?,?,?,?,?,?)');$s->execute([$ref,$date,$branch,$brand,$_POST['payment_method']??'cash',$total,$total,trim($_POST['notes']??''),user()['id']]);$id=(int)$pdo->lastInsertId();$pdo->prepare('INSERT INTO sale_items(sale_id,product_id,quantity,unit_price,line_total) VALUES(?,?,?,?,?)')->execute([$id,$product,$qty,$price,$total]);}
  elseif($module==='receiving'){$total=$qty*$price;$s=$pdo->prepare('INSERT INTO stock_receivings(reference_no,received_date,branch_id,brand_id,supplier_id,invoice_no,total_cost,notes,created_by) VALUES(?,?,?,?,?,?,?,?,?)');$s->execute([$ref,$date,$branch,$brand,$_POST['supplier_id']?:null,trim($_POST['invoice_no']??''),$total,trim($_POST['notes']??''),user()['id']]);$id=(int)$pdo->lastInsertId();$pdo->prepare('INSERT INTO stock_receiving_items(receiving_id,product_id,quantity,unit_cost,line_total) VALUES(?,?,?,?,?)')->execute([$id,$product,$qty,$price,$total]);}
  elseif($module==='usage'){$s=$pdo->prepare('INSERT INTO stock_usages(reference_no,usage_date,branch_id,brand_id,department,reason,notes,created_by,approved_by) VALUES(?,?,?,?,?,?,?,?,?)');$s->execute([$ref,$date,$branch,$brand,trim($_POST['department']??''),trim($_POST['reason']??''),trim($_POST['notes']??''),user()['id'],user()['id']]);$id=(int)$pdo->lastInsertId();$pdo->prepare('INSERT INTO stock_usage_items(usage_id,product_id,quantity) VALUES(?,?,?)')->execute([$id,$product,$qty]);}
  else{$p=$pdo->prepare('SELECT cost_price FROM products WHERE id=?');$p->execute([$product]);$cost=(float)$p->fetchColumn();$impact=$cost*$qty;$s=$pdo->prepare('INSERT INTO wastages(reference_no,wastage_date,branch_id,brand_id,reason,cost_impact,notes,created_by,approved_by) VALUES(?,?,?,?,?,?,?,?,?)');$s->execute([$ref,$date,$branch,$brand,trim($_POST['reason']??'Other'),$impact,trim($_POST['notes']??''),user()['id'],user()['id']]);$id=(int)$pdo->lastInsertId();$pdo->prepare('INSERT INTO wastage_items(wastage_id,product_id,quantity,unit_cost) VALUES(?,?,?,?)')->execute([$id,$product,$qty,$cost]);}
  ledger($pdo,['product_id'=>$product,'branch_id'=>$branch,'brand_id'=>$brand,'transaction_type'=>$d['type'],'reference_type'=>$module,'reference_id'=>$id,'reference_no'=>$ref,'quantity_in'=>$d['direction']==='in'?$qty:0,'quantity_out'=>$d['direction']==='out'?$qty:0,'notes'=>$_POST['notes']??null]);audit($pdo,'create',$module,$id,null,['reference'=>$ref,'quantity'=>$qty]);$pdo->commit();flash('success',$d['title'].' entry '.$ref.' saved successfully.');redirect($module.'.php');
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('error',$e->getMessage());redirect($module.'.php?action=create');}
}
$create=($_GET['action']??'')==='create';$branches=options($pdo,'branches');$brands=options($pdo,'brands');$products=options($pdo,'products');$suppliers=$module==='receiving'?options($pdo,'suppliers'):[];
render_header($d['title'],$module);page_title($d['title'],$d['eyebrow'],$d['desc'],$create?'':'Add '.$d['title'],app_url($module.'.php?action=create'));
if($create): ?>
<article class="card form-card"><div class="card-head"><div><h2>New <?=e($d['title'])?> entry</h2><small>The inventory ledger will update automatically after saving.</small></div><span class="status">SECURE ENTRY</span></div><form method="post"><?=csrf_field()?><div class="form-grid"><label>Date<input type="date" name="date" value="<?=date('Y-m-d')?>" required></label><label>Branch<select name="branch_id" required><option value="">Select branch</option><?php foreach($branches as $x):?><option value="<?=$x['id']?>"><?=e($x['label'])?></option><?php endforeach;?></select></label><label>Brand<select name="brand_id" required><option value="">Select brand</option><?php foreach($brands as $x):?><option value="<?=$x['id']?>"><?=e($x['label'])?></option><?php endforeach;?></select></label><label>Product<select name="product_id" required><option value="">Select product</option><?php foreach($products as $x):?><option value="<?=$x['id']?>"><?=e($x['label'])?></option><?php endforeach;?></select></label><label>Quantity<input type="number" name="quantity" step="0.001" min="0.001" required></label><?php if(in_array($module,['sales','receiving'])):?><label><?= $module==='sales'?'Unit selling price':'Unit cost' ?><input type="number" name="unit_price" step="0.01" min="0" required></label><?php endif;?><?php if($module==='sales'):?><label>Payment method<select name="payment_method"><option value="cash">Cash</option><option value="card">Card</option><option value="online">Online</option><option value="bank">Bank</option><option value="other">Other</option></select></label><?php elseif($module==='receiving'):?><label>Supplier<select name="supplier_id"><option value="">No supplier</option><?php foreach($suppliers as $x):?><option value="<?=$x['id']?>"><?=e($x['label'])?></option><?php endforeach;?></select></label><label>Supplier invoice<input name="invoice_no" maxlength="100"></label><?php elseif($module==='usage'):?><label>Department<input name="department" placeholder="Kitchen / Production"></label><label>Reason<input name="reason" placeholder="Production usage"></label><?php else:?><label>Wastage reason<select name="reason"><option>Expired</option><option>Damaged</option><option>Spoiled</option><option>Preparation Loss</option><option>Quality Issue</option><option>Accidental Damage</option><option>Other</option></select></label><?php endif;?><label class="full">Notes<textarea name="notes" placeholder="Optional operational notes"></textarea></label></div><div class="form-actions"><a class="btn" href="<?=app_url($module.'.php')?>">Cancel</a><button class="btn primary" type="submit">Save & update ledger</button></div></form></article>
<?php else:
[$period,$from,$to,$branch,$brand]=page_params();$where=["x.{$d['date']} BETWEEN ? AND ?",'x.deleted_at IS NULL'];$args=[$from,$to];if($branch){$where[]='x.branch_id=?';$args[]=$branch;}if($brand){$where[]='x.brand_id=?';$args[]=$brand;}$page=max(1,(int)($_GET['page']??1));$per=12;$count=$pdo->prepare('SELECT COUNT(*) FROM '.$d['table'].' x WHERE '.implode(' AND ',$where));$count->execute($args);$total=(int)$count->fetchColumn();$pages=max(1,(int)ceil($total/$per));$offset=($page-1)*$per;
$sql='SELECT x.*,b.name branch,br.name brand,u.name entered_by FROM '.$d['table'].' x JOIN branches b ON b.id=x.branch_id JOIN brands br ON br.id=x.brand_id JOIN users u ON u.id='.($module==='transfers'?'x.requested_by':'x.created_by').' WHERE '.implode(' AND ',$where).' ORDER BY x.id DESC LIMIT '.$per.' OFFSET '.$offset;$s=$pdo->prepare($sql);$s->execute($args);$rows=$s->fetchAll();?>
<div class="page-head" style="margin-top:-8px"><div></div><?php filter_bar($pdo);?></div><article class="card table-card"><div class="table-toolbar"><div><b><?=number_format($total)?> records</b><small style="display:block;color:var(--muted);margin-top:4px">Filtered operational history</small></div><a class="btn small" href="<?=app_url('reports.php?type='.$module)?>">Export report</a></div><div class="table-wrap"><table><thead><tr><th>Reference</th><th>Date</th><th>Branch</th><th>Brand</th><?php if($d['amount']):?><th>Amount</th><?php endif;?><th>Status</th><th>Entered by</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td data-label="Reference"><b><?=e($r['reference_no'])?></b></td><td data-label="Date"><?=date('d M Y',strtotime($r[$d['date']]))?></td><td data-label="Branch"><?=e($r['branch'])?></td><td data-label="Brand"><?=e($r['brand'])?></td><?php if($d['amount']):?><td data-label="Amount"><?=money($r[$d['amount']])?></td><?php endif;?><td data-label="Status"><span class="status <?=e($r['status']==='cancelled'?'cancelled':($r['status']==='pending'?'pending':''))?>"><?=e(ucfirst($r['status']))?></span></td><td data-label="Entered by"><?=e($r['entered_by'])?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="8"><div class="empty"><div class="empty-icon"><i data-icon="inbox"></i></div>No records match this period.</div></td></tr><?php endif;?></tbody></table></div><?php pager($page,$pages);?></article>
<?php endif; render_footer($module);
